object MntIcons {
    // Phosphor draws on 256 with a wide margin; the viewport is cut to 224 so a glyph fills its box,
    // or to the [box] a glyph that reaches into the margin needs, so nothing of it is clipped.
    private fun icon(name: String, vararg paths: Pair<String, Float>, box: Float = 224f) =
        ImageVector.Builder(name, 24.dp, 24.dp, box, box).apply {
            addGroup(translationX = (box - 256f) / 2, translationY = (box - 256f) / 2)
            paths.forEach { (data, alpha) -> addPath(PathParser().parsePathString(data).toNodes(), fill = SolidColor(Color.Black), fillAlpha = alpha) }
            clearGroup()
        }.build()

